# Save the Python program
program_code = '''def transform(grid):
    n = len(grid)
    box_rows = []
    max_width = 0
    for r in range(n):
        cols_with_5 = [c for c in range(n) if grid[r][c] == 5]
        if cols_with_5:
            width = max(cols_with_5) - min(cols_with_5) + 1
            if width >= max_width:
                max_width = width
                box_rows.append((r, min(cols_with_5), max(cols_with_5)))

    if not box_rows or max_width == 0:
        return grid

    box_min_row = min(r for r, c1, c2 in box_rows)
    box_max_row = max(r for r, c1, c2 in box_rows)
    box_min_col = min(c1 for r, c1, c2 in box_rows)
    box_max_col = max(c2 for r, c1, c2 in box_rows)

    chips = []

    above_row = box_min_row - 1
    if above_row >= 0:
        for c in range(max(0, box_min_col - 2), min(n, box_max_col + 2)):
            if above_row >= 0 and grid[above_row][c] != 0 and grid[above_row][c] != 5:
                chips.append((c, grid[above_row][c]))

    if not chips:
        below_row = box_max_row + 1
        if below_row < n:
            for c in range(max(0, box_min_col - 2), min(n, box_max_col + 2)):
                if grid[below_row][c] != 0 and grid[below_row][c] != 5:
                    chips.append((c, grid[below_row][c]))

    if len(chips) != 2:
        return grid

    chips.sort(key=lambda x: x[0])
    positional_left = chips[0][1]
    positional_right = chips[1][1]

    small_val = min(positional_left, positional_right)
    large_val = max(positional_left, positional_right)

    output = [row[:] for row in grid]

    inner_height = box_max_row - box_min_row - 1
    inner_width = box_max_col - box_min_col - 1
    half_h = inner_height // 2
    half_w = inner_width // 2

    for r in range(box_min_row + 1, box_max_row):
        for c in range(box_min_col + 1, box_max_col):
            inner_r = r - (box_min_row + 1)
            inner_c = c - (box_min_col + 1)

            if inner_r < half_h:
                if inner_c < half_w:
                    output[r][c] = small_val
                else:
                    output[r][c] = large_val
            else:
                if inner_c < half_w:
                    output[r][c] = large_val
                else:
                    output[r][c] = small_val

    return output
'''

